-- TEST ONLY minimal columns used by actual fixed read query; no production grants.
-- Full migrations/native transition are not simulated or claimed by this fixture.
CREATE SCHEMA private_baden_history;
CREATE SCHEMA private_historical_statistics;
CREATE SCHEMA private_fussball;
CREATE TABLE countries(id bigint PRIMARY KEY,code text);
CREATE TABLE competitions(id bigint PRIMARY KEY,slug text,source text,source_policy text,source_league_code text,country_id bigint,active boolean,prvi_fantasy_krog int,rok_pomak_ur int);
CREATE TABLE teams(id bigint PRIMARY KEY,name text,country_id bigint);
CREATE TABLE rounds(id bigint PRIMARY KEY,competition_id bigint,season text,number int,played_on date,deadline_at timestamptz,lineups_locked_at timestamptz);
CREATE TABLE matches(id bigint PRIMARY KEY,round_id bigint,home_team_id bigint,away_team_id bigint,zapisnik_id text,source_url text,played_on date,home_goals int,away_goals int,statistics_status text,imported_at timestamptz,source_round int,source_phase text,vir_brez_izida boolean,kontumacija boolean);
CREATE TABLE private_baden_history.catalog(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),manifest jsonb NOT NULL,manifest_sha256 text NOT NULL CHECK(manifest_sha256~'^[a-f0-9]{64}$'));
CREATE TABLE private_baden_history.prepared(competition_id bigint PRIMARY KEY REFERENCES competitions(id),manifest_sha256 text NOT NULL,bindings jsonb NOT NULL,opening_round_id bigint NOT NULL REFERENCES rounds(id));
CREATE TABLE private_baden_history.club_bindings(competition_id bigint NOT NULL REFERENCES competitions(id),source_competition_id text NOT NULL,season text NOT NULL,source_club_id text NOT NULL,name text NOT NULL,team_id bigint NOT NULL REFERENCES teams(id),PRIMARY KEY(competition_id,source_club_id));
CREATE TABLE private_historical_statistics.installed_policies(competition_id bigint,policy_id text,policy_sha256 text,first_fantasy_played_on date);
CREATE TABLE private_historical_statistics.policies(id text,policy_sha256 text,document jsonb);
CREATE TABLE private_historical_statistics.markers(competition_id bigint,source_match_id text,fixture jsonb,raw_sha256 text);
CREATE TABLE private_historical_statistics.source_club_bindings(provider text,source_club_id text);
CREATE TABLE competition_settings(competition_id bigint,key text,value jsonb);
CREATE TABLE private_fussball.card_policies(competition_id bigint);
CREATE TABLE players(id bigint,competition_id bigint);
CREATE TABLE appearances(match_id bigint);
CREATE TABLE goals(id bigint,match_id bigint);
CREATE TABLE player_scores(round_id bigint);
CREATE TABLE tocke_krogov(round_id bigint);
CREATE TABLE fantasy_teams(id bigint,competition_id bigint);
CREATE TABLE fantasy_lineups(round_id bigint);
CREATE TABLE fantasy_roster(fantasy_team_id bigint,player_id bigint);
CREATE TABLE fantasy_transfers(round_id bigint);
CREATE TABLE fantasy_chips(round_id bigint);
CREATE TABLE position_votes(player_id bigint);
CREATE TABLE assist_votes(goal_id bigint);
CREATE TABLE ratings(round_id bigint);
CREATE TABLE private_fussball.card_reports(id bigint,competition_id bigint);
CREATE TABLE private_fussball.card_events(id bigint,report_id bigint);
CREATE TABLE private_fussball.card_votes(event_id bigint);
CREATE TABLE private_fussball.card_heads(match_id bigint);
CREATE TABLE private_fussball.card_admissions(competition_id bigint);
CREATE TABLE private_fussball.card_activation_context(competition_id bigint);
CREATE TABLE private_fussball.card_write_context(match_id bigint);
-- Exact merged canonical_json algorithm, same C collation/array order.
CREATE FUNCTION private_fussball.canonical_json(v jsonb)RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE result text;BEGIN CASE jsonb_typeof(v)WHEN 'object'THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||private_fussball.canonical_json(value),','ORDER BY key COLLATE "C"),'')||'}'INTO result FROM jsonb_each(v);WHEN 'array'THEN SELECT '['||coalesce(string_agg(private_fussball.canonical_json(value),','ORDER BY ordinal),'')||']'INTO result FROM jsonb_array_elements(v)WITH ORDINALITY x(value,ordinal);ELSE result:=v::text;END CASE;RETURN result;END$$;
CREATE TEMP TABLE fixture AS SELECT convert_from(decode('TEST_ONLY_SNAPSHOT_HEX','hex'),'UTF8')::jsonb AS s;
INSERT INTO countries SELECT * FROM jsonb_populate_recordset(NULL::countries,(SELECT s->'countries'FROM fixture));
INSERT INTO competitions SELECT * FROM jsonb_populate_recordset(NULL::competitions,(SELECT s->'competition'FROM fixture));
INSERT INTO teams SELECT DISTINCT(b->>'team_id')::bigint,b->>'name',66 FROM fixture CROSS JOIN LATERAL jsonb_array_elements(s->'clubs')b;
INSERT INTO rounds SELECT * FROM jsonb_populate_recordset(NULL::rounds,(SELECT s->'rounds'FROM fixture));
INSERT INTO matches SELECT * FROM jsonb_populate_recordset(NULL::matches,(SELECT s->'matches'FROM fixture));
INSERT INTO private_baden_history.catalog SELECT * FROM jsonb_populate_recordset(NULL::private_baden_history.catalog,(SELECT s->'catalog'FROM fixture));
INSERT INTO private_baden_history.prepared SELECT * FROM jsonb_populate_recordset(NULL::private_baden_history.prepared,(SELECT s->'prepared'FROM fixture));
INSERT INTO private_baden_history.club_bindings SELECT * FROM jsonb_populate_recordset(NULL::private_baden_history.club_bindings,(SELECT s->'clubs'FROM fixture));
INSERT INTO private_historical_statistics.installed_policies SELECT * FROM jsonb_populate_recordset(NULL::private_historical_statistics.installed_policies,(SELECT s->'installedPolicy'FROM fixture));
INSERT INTO private_historical_statistics.policies SELECT * FROM jsonb_populate_recordset(NULL::private_historical_statistics.policies,(SELECT s->'policy'FROM fixture));
INSERT INTO private_historical_statistics.markers SELECT * FROM jsonb_populate_recordset(NULL::private_historical_statistics.markers,(SELECT s->'markers'FROM fixture));
